import type { WorkerRun } from "../ConversationRuntime";
import { statusLabel } from "../presentation";
import type { TimelineEvent } from "../timeline";
import EventGroup from "./conversation/EventGroup";
import { Chevron } from "./conversation/Icons";
import { StatusIndicator, type RunState } from "./conversation/RunStatus";
import { text, type EventViewMemory, type HistoryProps, type Quest } from "./conversation/eventModel";

export interface SubagentEntryProps extends HistoryProps {
  run: WorkerRun;
  events: TimelineEvent[];
  quests: Quest[];
  memory: EventViewMemory;
  onQuest: (id: string) => void;
  onOpenFile?: (path: string) => void;
  onInspect: () => void;
}

const terminalStates = new Set(["succeeded", "failed", "cancelled"]);
const count = (value: unknown) => typeof value === "number" && Number.isSafeInteger(value) && value >= 0 ? value.toLocaleString() : "未知";

/** The current activity snapshot and the recorded process events remain distinct. */
export default function SubagentEntry({ run, events, quests, memory, onQuest, onOpenFile, onInspect, ...history }: SubagentEntryProps) {
  if (!memory.subagents) memory.subagents = new Map();
  if (!memory.subagents.has(run.run_id)) memory.subagents.set(run.run_id, {});
  const saved = memory.subagents.get(run.run_id)!;
  const terminal = terminalStates.has(run.state || "");
  const [expanded, setExpanded] = useState(() => saved.expanded ?? !terminal);
  // Derive untouched terminal collapse in this render, before the parent restores its anchor.
  const visible = saved.manual ? expanded : !terminal;
  const quest = quests.find((item) => item.id === run.quest_id);
  const state: RunState = run.state === "running" || run.state === "queued" ? "running" : run.state === "succeeded" ? "completed"
    : run.state === "failed" ? "failed" : !run.state || run.state === "unknown" || run.state === "uncertain" ? "unknown" : "recorded";
  const mode = (run as WorkerRun & { execution_mode?: unknown }).execution_mode;
  const currentSource = mode === "mock" ? "模拟" : mode === "live" ? "真实执行" : "执行来源未记录";
  const hasMock = events.some((event) => event.execution_mode === "mock");
  return <details className="subagent-entry" data-state={run.state || "unknown"} data-run-id={run.run_id} data-scroll-key={`subagent:${run.run_id}`} open={visible}>
    <summary aria-expanded={visible} aria-label={`子智能体 ${text(run.role, "角色未记录")} · ${statusLabel(run.state)}`} onClick={(event) => {
      event.preventDefault();
      onInspect();
      saved.manual = true;
      saved.expanded = !visible;
      setExpanded(!visible);
    }}>
      <span className="subagent-icon"><StatusIndicator state={state} /></span>
      <span className="subagent-label">子智能体</span><strong className="subagent-role">{text(run.role, "角色未记录")}</strong>
      <span className="subagent-model" title={[run.provider_id, run.model_id].filter(Boolean).join(" / ")}>{text(run.model_id, "模型未记录")}</span>
      <span className="subagent-state" data-state={run.state || "unknown"}>{statusLabel(run.state)}</span>
      <span className="subagent-progress">已记录 {count(run.steps)} 步 · {count(run.tool_spent)} 次工具</span>
      {hasMock && <small className="subagent-mode">含模拟记录</small>}<Chevron />
    </summary>
    <div className="subagent-body" onPointerDownCapture={() => { saved.manual = true; }} onKeyDownCapture={() => { saved.manual = true; }}>
      <p className="subagent-scope">{quest?.title || text(run.quest_id, "关联任务未记录")} · {text(run.provider_id, "供应商未记录")} · {currentSource}</p>
      <p className="subagent-record-notice">当前状态来自最近读取的执行记录。下方为已加载且关联本次 Run 的历史事件。</p>
      {events.length ? <EventGroup item={{ type: "group", questId: run.quest_id || null, events }} quests={quests} runs={[run]} memory={memory} visible={visible}
        onQuest={onQuest} onOpenFile={onOpenFile} onInspect={onInspect} {...history} /> : <p className="subagent-record-notice">尚未加载本次执行的过程记录。</p>}
      <div className="subagent-actions">{run.quest_id && <button type="button" className="text-button" onClick={() => { onInspect(); onQuest(run.quest_id!); }}>任务详情</button>}
        <span className="subagent-run-id" title={run.run_id}>Run · {run.run_id}</span>
      </div>
    </div>
  </details>;
}

# 开发协作约定

这些约定适用于整个仓库。用户在当前会话中的明确指令优先；子目录存在更具体的约定时，同时遵循适用的目录约定。

- 修改前先阅读 README、相关代码和适用的目录说明，确认当前 Git 状态。
- 优先使用内置补丁工具编辑文件；无法使用时，立即改用 PowerShell。写入文本时使用 UTF-8。
- 保留用户已有的改动，围绕当前任务修改代码。
- 开发方向包含 Python、JSON、前端和 Tauri。前端框架、应用结构以及 Python 与 Tauri 的交互方式仍待确定，新增框架和依赖时以用户需求及已有代码为依据。
- Python 代码遵循现有项目规范；JSON 使用有效语法；Tauri 原生命令遵循最小必要权限原则。
- 修改完成后，运行与改动相关的检查；在交付说明中写明结果和未完成事项。
- 新增依赖、启动步骤或必要环境变量时，同步更新 README；示例中只使用占位值。
- 除非用户指定其他分支，新功能分支使用 `codex/` 前缀。

# FORGE desktop

React 18、Tauri 2、TypeScript、Vite 与分层原生 CSS。保留每个工作空间的一条长期对话：Router 负责协调，Worker 使用私有执行上下文，后台任务和交付回到同一条对话。

```powershell
npm test
npm run build
npm run dev -- --port 5173
```

没有新增应用依赖。原生调试沿用现有 Core runtime 设置；当前锁定 Rust 依赖在本机使用已安装的 Rust 1.90 验证。Git 变更预览需要 PATH 中存在 Git。

## 导航、任务与设置

普通布局使用 260px 单栏侧边栏与 36px 标题栏，可完全收起侧栏；760px 以下侧栏为浮层。标题栏提供返回/前进、文件/编辑/视图/帮助菜单和组件心跳入口。HTML 保留 16px rem 基准，UI 使用独立 14px 字号，`--spacing:.25rem` 解析为 4px。当前真实工作空间作为可展开项目，只有一个对话入口；置顶与最近分组不会伪造额外会话。项目发现只读展示后端已发现目录，未提供跨空间切换、项目 CRUD 或目录授权。Ctrl+, 打开设置。

后台任务按明确的 project/workspace ID、路径或 metadata 归属分组；缺省归当前工作空间，不从任务名称猜项目。同名但不同 ID 的项目保持独立。组内需处理、运行任务优先，已结束任务默认折叠；支持搜索项目名称/路径/任务、筛选与键盘导航。计数仅表示已加载记录，轮询保留选择、折叠和滚动。

`/api/settings` 与任务读取提供 version 1 的 `project_context`：当前 workspace 的 ID、名称、根目录及默认项目键，明确 `scope=current_workspace`。侧栏与任务共用 `projectContext.ts`，同时解析 Core 实际存储的 JSON 字符串 metadata 与对象。metadata 仅用于分组，不授予目录权限；契约明确不支持跨空间切换或项目 CRUD。

设置按现有功能分为三组九项：常规、键盘快捷键、模型库、运行配置、用量与预算、记忆、触发器、供应商凭据、备份与恢复。采用左导航与右内容两栏，窄屏切换为顶部横向导航。分类栏通常为 288px，内容列最大 768px（含内部 20px 边距），导航行 30px、实际标签 14px/21px，设置行标签 13px/18.5714px、说明 12px/16px。表单选择 compact 输入与 md 按钮变体，28px 高、13px 字号。模型档案保留新增、编辑、启停，能力、价格与技术记录按需展开，未知值不推断为支持。

模型发现与固定样例测量使用现有 Provider；只有点击按钮才会调用，测量会消耗预算且失败不自动重试。触发器提供事件源注册、事件接收、定时任务和文件监听语义表单。后端只提供 pending 事件列表，UI 不将其冒充全部源、定时任务或监听清单；创建回执仅保留于本次打开页面。

