import { useState } from "react";
import type { ActivityState, WorkerRun } from "../ConversationRuntime";
import { WorkerRunDetails } from "../ConversationRuntime";
import { statusLabel } from "../presentation";
import AgentAvatar from "./AgentAvatar";

interface AgentPanelProps {
  state: ActivityState;
  sources: string[];
  filesChanged?: number;
  onChanges: () => void;
  onSource: (path: string) => void;
  onRun: (run: WorkerRun) => void;
  onActivity: () => void;
  onClose: () => void;
}

/** A persistent conversation companion, with identities shared by the transcript. */
export default function AgentPanel({ state, sources, filesChanged, onChanges, onSource, onRun, onActivity, onClose }: AgentPanelProps) {
  const [expanded, setExpanded] = useState(false), [allSources, setAllSources] = useState(false);
  const [menu, setMenu] = useState(false);
  const runs = state.connected && !state.error ? state.items : [];
  const done = runs.filter(run => run.state === "succeeded").length;
  const active = runs.filter(run => ["running", "queued"].includes(run.state || "")).length;
  const failed = runs.filter(run => run.state === "failed").length;
  const summary = state.error ? "暂不可用" : state.loading && !runs.length ? "正在读取…" : !state.connected ? "未连接"
    : [active ? `${active} 运行中` : "", done ? `${done} 完成` : "", failed ? `${failed} 失败` : "", !active && !done && !failed && runs.length ? `${runs.length} 条记录` : ""].filter(Boolean).join(" · ") || "暂无运行";
  return <aside className="agent-panel" aria-label="Agent 面板">
    <header className="agent-panel-header"><span>Agent</span><div className="agent-panel-menu-anchor">
      <button type="button" className="agent-panel-more" aria-label="Agent 面板菜单" aria-expanded={menu} onClick={() => setMenu(!menu)} onKeyDown={event => { if (event.key === "Escape") setMenu(false); }}>···</button>
      {menu && <div className="agent-panel-menu"><button type="button" onClick={() => { setMenu(false); onActivity(); }}>查看运行活动</button><button type="button" onClick={() => { setMenu(false); onClose(); }}>隐藏 Agent 面板</button></div>}
    </div></header>
    <button type="button" className="agent-panel-changes" onClick={onChanges}>
      <svg viewBox="0 0 20 20" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.4" aria-hidden="true"><rect x="3" y="2.5" width="14" height="15" rx="3" /><path d="M10 6v7m-3.5-3.5h7" /></svg>
      <span>变更</span>{typeof filesChanged === "number" && <small>{filesChanged}</small>}
    </button>
    <section className="agent-panel-section">
      <button type="button" className="agent-panel-section-title" aria-expanded={expanded} aria-controls="agent-panel-runs" onClick={() => setExpanded(!expanded)}>子智能体<svg viewBox="0 0 16 16" width="14" height="14" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><path d={expanded ? "m4 10 4-4 4 4" : "m4 6 4 4 4-4"} /></svg></button>
      <button type="button" className="agent-panel-summary" aria-label={`展开子智能体：${summary}`} aria-expanded={expanded} onClick={() => setExpanded(!expanded)}>
        <span className="agent-avatar-stack">{runs.slice(0, 5).map(run => <AgentAvatar key={run.run_id} identity={run.worker_id || run.run_id} />)}</span><span>{summary}</span>
      </button>
      {state.error && <p className="agent-panel-notice" role="status">无法读取当前状态。<button type="button" onClick={onActivity}>查看运行活动</button></p>}
      <div id="agent-panel-runs" className="agent-panel-runs" hidden={!expanded}>
        {runs.map(run => <div className="agent-panel-run" key={run.run_id} data-run-id={run.run_id}>
          <button type="button" className="agent-panel-run-button" onClick={() => onRun(run)} title={run.model_id || undefined}><AgentAvatar identity={run.worker_id || run.run_id} /><span>{run.role || "子智能体"}</span><small data-state={run.state}>{statusLabel(run.state)}</small></button>
          <WorkerRunDetails run={run} runId={run.run_id} />
        </div>)}
        {state.hasMore && <button type="button" className="agent-panel-all" onClick={onActivity}>查看更早的运行</button>}
      </div>
    </section>
    <section className="agent-panel-section agent-panel-sources"><div className="agent-panel-sources-heading"><span>来源</span><button type="button" aria-label="浏览工作空间文件" onClick={() => onSource("")}>＋</button></div>
      {sources.length ? <>{sources.slice(0, allSources ? sources.length : 3).map(path => <button type="button" className="agent-panel-source" key={path} onClick={() => onSource(path)} title={path}>
        <svg viewBox="0 0 18 18" width="18" height="18" fill="none" stroke="currentColor" strokeWidth="1.3" aria-hidden="true"><path d="M4 2h6l4 4v10H4V2Zm6 0v4h4" /></svg><span>{path.split(/[\\/]/).pop()}</span>
      </button>)}{sources.length > 3 && <button type="button" className="agent-panel-all" aria-expanded={allSources} onClick={() => setAllSources(!allSources)}>{allSources ? "收起来源" : `查看全部 ${sources.length} 项`}</button>}</> : <p className="agent-panel-empty">暂无文件来源</p>}
    </section>
  </aside>;
}

const colors = ["#c7a43d", "#c775a1", "#7c9e5e", "#8498d5", "#c88856", "#a58acb"];

/** Keep an agent's flower identity stable across polling, state changes and new runs. */
export function agentAppearance(identity: string) {
  let hash = 2166136261;
  for (let index = 0; index < identity.length; index++) hash = Math.imul(hash ^ identity.charCodeAt(index), 16777619);
  const value = hash >>> 0;
  return { color: colors[value % colors.length], shape: (value >>> 3) % 4 };
}

/** A code-native flower mark, separate from the changing execution status. */
export default function AgentAvatar({ identity, className = "", size = 18 }: { identity: string; className?: string; size?: number }) {
  const { color, shape } = agentAppearance(identity);
  const petals = shape === 1 ? 6 : shape === 2 ? 5 : 8;
  return <svg className={`agent-avatar ${className}`.trim()} width={size} height={size} viewBox="0 0 24 24" fill="currentColor" style={{ color }} aria-hidden="true" focusable="false" data-agent-shape={shape}>
    {Array.from({ length: petals }, (_, index) => <g key={index} transform={`rotate(${index * 360 / petals} 12 12)`}>
      {shape === 0 ? <ellipse cx="12" cy="6.5" rx="2.2" ry="4.5" />
        : shape === 1 ? <path d="M11.1 11.8C7.8 9.6 7.3 5.1 10.2 3.6c3.2-1.7 5.9 1.2 4.7 4.2-.5 1.4-1.7 2.9-3.8 4Z" />
        : shape === 2 ? <ellipse cx="12" cy="6.7" rx="3.5" ry="4.8" />
        : <path d="M12 11.6c-2.6-2-3.6-6.5-1.9-9.5 3.8 1.4 5 5.7 1.9 9.5Z" />}
    </g>)}
    <circle cx="12" cy="12" r={shape === 2 ? 2.3 : 2.6} fill="currentColor" />
    <circle cx="12" cy="12" r="1.25" fill="currentColor" opacity=".45" style={{ filter: "brightness(0.65)" }} />
  </svg>;
}

// Synthetic HTTP acceptance for the six-stage frontend. No live model calls.
async (page, { outputDir }) => {
  const checks = [], missing = [], calls = [];
  const check = (ok, label) => { if (!ok) throw new Error(label); checks.push(label); };
  const quest = { id: 'quest-ui', title: '核对前端改造', goal: '检查界面与交互', status: 'running', version: 3, plan_revision: 2 };
  const messages = [
    { id: 'm-user', role: 'user', content: '阅读项目资料，整理改造方案。', created_at: '2026-11-16T08:00:00Z' },
    { id: 'm-agent', role: 'assistant', content: '我会核对项目结构，并把资料研究与界面检查交给后台成员。\n\n- 保留当前接口契约\n- 核对文件与测试结果\n\n```ts\nconst workspace = "FORGE";\n```', created_at: '2026-11-16T08:00:04Z', metadata: { model_id: 'router-fixture', execution_mode: 'mock' } },
  ];
  let runs = [{ run_id: 'run-ui', worker_id: 'worker-ui', quest_id: quest.id, role: '界面检查', state: 'running', provider_id: 'fixture', model_id: 'review-fixture', steps: 2, tool_spent: 1, created_at: '2026-11-16T08:00:02Z' }];
  await page.route('http://127.0.0.1:8765/**', async (route) => {
    const req = route.request(), url = new URL(req.url()), method = req.method();
    const headers = { 'access-control-allow-origin': '*', 'access-control-allow-headers': '*', 'access-control-allow-methods': 'GET,POST,PATCH,OPTIONS' };
    if (method === 'OPTIONS') return route.fulfill({ status: 204, headers });
    calls.push(`${method} ${url.pathname}`);
    let body, status = 200;
    if (url.pathname === '/health') body = { session: 'refactor-ui' };
    else if (url.pathname === '/api/conversation') body = { messages, router: { router_session_id: 'router-ui' }, has_more: false };
    else if (url.pathname === '/api/quests') body = { items: [quest], has_more: false };
    else if (url.pathname === '/api/quests/quest-ui') body = { quest, workers: runs };
    else if (url.pathname.endsWith('/plan')) body = { plan_revision: 2, status: 'approved', digest: 'a'.repeat(64), nodes: [] };
    else if (url.pathname.endsWith('/plan/history')) body = [];
    else if (url.pathname.endsWith('/grants') || url.pathname.endsWith('/teams')) body = [];
    else if (url.pathname === '/api/activity') body = { items: runs, has_more: false };
    else if (url.pathname === '/api/approvals/pending' || url.pathname === '/api/approvals') body = { items: [], has_more: false };
    else if (url.pathname === '/api/timeline') body = { items: [{ kind: 'tool_receipt', event_id: 'tool-ui', seq: 1, created_at: '2026-11-16T08:00:03Z', quest_id: quest.id, run_id: 'run-ui', worker_id: 'worker-ui', title: '工具调用', status: 'succeeded', execution_mode: 'mock', detail: { tool: 'file_read', path: 'README.md' } }], has_more: false };
    else if (url.pathname === '/api/settings') body = { revision: 0, config: null, workspace_id: 'workspace-ui', workspace_root: 'D:/Fixture/FORGE', router_model_id: 'router-fixture', provider_id: 'fixture', provider_configured: true, restore_fenced: false };
    else if (url.pathname === '/api/restore-status') body = { fenced: false };
    else if (url.pathname === '/api/projects/discovered') body = [{ id: 'discovered-ui', root: 'D:/Fixture/Reference', name: 'Reference', grants_tool_access: false }];
    else if (url.pathname === '/api/runtime/health') body = { components: [{ component: 'worker', state: 'ok', last_seen: Date.now() / 1000, timeout_seconds: 600, restart_count: 0 }] };
    else if (url.pathname === '/api/models') body = [{ id: 'model-ui', model_id: 'router-fixture', provider: 'fixture', display_name: 'Router fixture', enabled: true }];
    else if (url.pathname === '/api/budget') body = { token_limit: 10000, concurrency_limit: 2 };
    else if (url.pathname === '/api/memory') body = { items: [], cursor: null };
    else if (url.pathname === '/api/triggers' || url.pathname === '/api/events') body = [];
    else { missing.push(`${method} ${url.pathname}`); status = 404; body = { detail: 'No synthetic fixture' }; }
    await route.fulfill({ status, headers, contentType: 'application/json', body: JSON.stringify(body) });
  });
  await page.emulateMedia({ colorScheme: 'light' });
  await page.goto('http://127.0.0.1:5173/');
  await page.getByLabel('Core 启动密钥').fill('ab'.repeat(32));
  await page.getByRole('button', { name: '连接', exact: true }).click();
  await page.locator('.from-agent').first().waitFor();
  await page.waitForTimeout(220);
  const width = await page.locator('.rail').evaluate((el) => el.getBoundingClientRect().width);
