const colors = ["#c7a43d", "#c775a1", "#7c9e5e", "#8498d5", "#c88856", "#a58acb"];

/** Keep an agent's flower identity stable across polling, state changes and new runs. */
export function agentAppearance(identity: string) {
  let hash = 2166136261;
  for (let index = 0; index < identity.length; index++) hash = Math.imul(hash ^ identity.charCodeAt(index), 16777619);
  const value = hash >>> 0;
  return { color: colors[value % colors.length], shape: (value >>> 3) % 4 };
}

/** A code-native flower mark, separate from the changing execution status. */
export default function AgentAvatar({ identity, className = "", size = 18 }: { identity: string; className?: string; size?: number }) {
  const { color, shape } = agentAppearance(identity);
  const petals = shape === 1 ? 6 : shape === 2 ? 5 : 8;
  return <svg className={`agent-avatar ${className}`.trim()} width={size} height={size} viewBox="0 0 24 24" fill="currentColor" style={{ color }} aria-hidden="true" focusable="false" data-agent-shape={shape}>
    {Array.from({ length: petals }, (_, index) => <g key={index} transform={`rotate(${index * 360 / petals} 12 12)`}>
      {shape === 0 ? <ellipse cx="12" cy="6.5" rx="2.2" ry="4.5" />
        : shape === 1 ? <path d="M11.1 11.8C7.8 9.6 7.3 5.1 10.2 3.6c3.2-1.7 5.9 1.2 4.7 4.2-.5 1.4-1.7 2.9-3.8 4Z" />
